insert into public.exercises (id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published) values ('00000000-0000-4000-8000-000000000001','Tracking com intenção','donwozi','8022-6842-4965','aim','both','beginner','Acompanhe alvos em movimento sem antecipar o disparo.','No SKAAVOK Aim Trainer, escolha um cenário de tracking. Use a mesma arma e configuração em cada tentativa. Faça blocos curtos e registre a precisão exibida, se disponível. Priorize manter a mira no alvo, sem perseguir velocidade.','Precisão (%) — mesmo cenário e arma','https://www.fortnite.com/@donwozi/8022-6842-4965','2026-10-10T03:00:00Z',true) on conflict(id) do nothing;
insert into public.exercises (id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published) values ('00000000-0000-4000-8000-000000000002','Edits, resets e precisão','raider464','2424-4344-7824','mechanics','build','intermediate','Uma sequência consistente vale mais que uma tentativa apressada.','No Mechanics Training V5, selecione um exercício de editing. Repita a mesma sequência, incluindo resets. Registre o número de execuções sem erro em dez tentativas. Aumente o ritmo somente quando conseguir repetir com controle.','Execuções corretas em 10 tentativas','https://www.fortnite.com/@raider464/2424-4344-7824','2026-10-10T03:00:00Z',true) on conflict(id) do nothing;
insert into public.exercises (id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published) values ('00000000-0000-4000-8000-000000000003','Piece control e peeks','jivantv','7037-5244-5527','piece','build','intermediate','Controle espaço antes de se expor ao oponente.','No How To Piece Control Map, escolha um cenário de controle de peças. Observe quais estruturas limitam a saída do adversário. Execute a tomada de espaço e um peek protegido. Registre quantas de dez tentativas terminaram sem exposição desnecessária.','Tentativas controladas em 10 — autoavaliação','https://www.fortnite.com/@jivantv/7037-5244-5527','2026-10-10T03:00:00Z',true) on conflict(id) do nothing;
insert into public.exercises (id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published) values ('00000000-0000-4000-8000-000000000004','Rotações sob pressão','jivantv','5473-5965-0108','competitive','build','advanced','Pratique o processo de decisão durante o avanço da zona.','No Forever Zone Wars, jogue um bloco de rodadas. Antes de mover, observe cobertura, recursos e direção da zona. Ao terminar, anote uma decisão que funcionou e uma que expôs você. A simulação não reproduz integralmente um torneio real.','Rotações com cobertura em 10 — autoavaliação','https://www.fortnite.com/@jivantv/5473-5965-0108','2026-10-10T03:00:00Z',true) on conflict(id) do nothing;
insert into public.exercises (id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published) values ('00000000-0000-4000-8000-000000000005','Freebuild com objetivo','reisshub','4175-6046-6184','mechanics','build','beginner','Treine uma sequência curta de construção e edição.','No Training Hub V2, escolha a área de freebuild. Defina uma sequência pequena com construção, edição e reset. Repita com precisão. No controle, ajuste o ritmo aos seus binds; no teclado e mouse, observe deslocamentos desnecessários. Não altere sensibilidade a cada erro.','Sequências sem erro em 10','https://www.fortnite.com/@reisshub/4175-6046-6184','2026-10-10T03:00:00Z',true) on conflict(id) do nothing;
insert into public.exercises (id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published) values ('00000000-0000-4000-8000-000000000006','Revisão de uma decisão','Método editorial',null,'vod','both','beginner','Transforme uma eliminação em uma hipótese de treino.','Reveja uma gravação própria. Pause antes da eliminação. Liste as informações disponíveis naquele momento, duas alternativas e a decisão tomada. Identifique um erro observável, sem avaliar apenas o resultado. Escolha um exercício para testar a alternativa.','Decisões revisadas — quantidade','https://www.fortnite.com/competitive','2026-10-10T03:00:00Z',true) on conflict(id) do nothing;
insert into public.exercises (id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published) values ('00000000-0000-4000-8000-000000000007','Cobertura e disengage','Método editorial',null,'decisions','zero','beginner','Avalie caminhos entre coberturas em Construção Zero.','Em uma gravação própria de Zero Build, pause antes de três deslocamentos. Identifique a próxima cobertura, uma rota alternativa e um caminho de recuo. Considere mobilidade e recursos disponíveis na versão atual. Não registre esses resultados como desempenho de mapa de mira.','Decisões com alternativa em 3 — autoavaliação','https://www.fortnite.com/competitive','2026-10-10T03:00:00Z',true) on conflict(id) do nothing;
insert into public.exercises (id,title,creator,map_code,category,mode,level,description,instructions,metric,source_url,verified_at,published) values ('00000000-0000-4000-8000-000000000008','Shotgun: mira antes do tiro','raider464','2424-4344-7824','aim','both','intermediate','Pratique posicionar a mira e confirmar o alvo.','Escolha um exercício de mira compatível no Mechanics Training V5. Use a mesma arma, distância e cenário entre sessões. Registre acertos em dez tentativas. O foco é a relação entre precisão e exposição; números deste exercício não são comparáveis aos de tracking.','Acertos em 10 — mesmo cenário','https://www.fortnite.com/@raider464/2424-4344-7824','2026-10-10T03:00:00Z',true) on conflict(id) do nothing;
insert into public.articles (id,slug,title,kind,category,summary,body,author,source_url,verified_at,published_at,valid_until,published) values ('00000000-0000-4000-8000-000000000101','fncs-solo-outubro-2026','FNCS Solo entra no calendário de outubro','news','fncs','A Epic anunciou uma competição Solo regional após o Campeonato Global de 2026.','O anúncio oficial de 29 de maio de 2026 incluiu um torneio FNCS Solo independente em outubro. Esta notícia registra o anúncio, não resultados ou elegibilidade individual.
